if($section==='keywords')echo '<div class="welcome-banner"><div><h3>Ready to see where you rank?</h3><p>Add your keywords here, then check their Google positions and track changes.</p></div><a class="button" href="'.url('/rankings?website_id='.$wid).'">Check Google rankings</a></div>';
