>← Previous</a><?php endif;?><span>Page <?=$page?> of <?=max(1,ceil($count/25))?></span><?php if($count>$page*25):?><a href="?website_id=<?=$wid?>&page=<?=$page+1?>&q=<?=urlencode($search)?>">Next →</a><?php endif;?></nav></div>
<div class="card stack" id="create"><h2><?=$edit?'Edit '.e($recordName):'Add a '.e($recordName)?></h2><form data-api="save"><input type="hidden" name="module" value="<?=e($section)?>"><input type="hidden" name="website_id" value="<?=$wid?>"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="form-grid"><?php foreach($def['fields'] as $key=>$label){if(is_array($label))select_field($key,$label[0],array_combine($label[1],array_map(fn($v)=>ucwords(str_replace('_',' ',$v)),$label[1])),$edit[$key]??'');elseif(in_array($key,['notes','description']))echo '<label>'.e($label).'<textarea name="'.e($key).'">'.e($edit[$key]??'').'</textarea></label>';else field($key,$label,$key==='due_date'?'date':($key==='budget'?'number':(str_contains($key,'url')||$key==='domain'?'url':'text')),$edit[$key]??(['country'=>'India','language'=>'en','search_engine'=>'google'][$key]??''),$key===$first || $key==='budget');}?></div><button class="button">Save <?=e($section==='human-services'?'request':'record')?> →</button></form></div>
<?php if(in_array($section,['keywords','backlinks'])):?><div class="card stack"><h3>Import CSV</h3><p class="small">UTF-8 CSV, up to 2 MB and 1,000 rows. Headers: <?=$section==='keywords'?'keyword,country,language,device,target_url,intent,tags,search_volume,difficulty,position':'source_url,target_url,anchor,follow,status,domain_rating'?>. Imports are atomic; invalid rows reject the file.</p><form data-api="import" enctype="multipart/form-data"><input type="hidden" name="module" value="<?=e($section)?>"><input type="hidden" name="website_id" value="<?=$wid?>"><?php field('csv','CSV file','file');?><button class="button secondary">Import CSV</button></form></div><?php endif; if($section==='content'&&isset($_GET['brief'])){$project=row('SELECT * FROM content_projects WHERE id=? AND website_id=?',[(int)$_GET['brief'],$wid]);if($project){$brief=row('SELECT * FROM content_briefs WHERE content_project_id=? ORDER BY id DESC LIMIT 1',[$project['id']]);?><div class="card stack"><h2><?=e($project['topic'])?> — content brief</h2><form data-api="content-brief" data-output="brief-output"><input type="hidden" name="website_id" value="<?=$wid?>"><input type="hidden" name="id" value="<?=$project['id']?>"><button class="button">✧ Generate with AI</button></form><pre id="brief-output"><?=e($brief['content']??'No brief saved yet. AI requires provider configuration.')?></pre><form data-api="save-brief"><input type="hidden" name="website_id" value="<?=$wid?>"><input type="hidden" name="id" value="<?=$project['id']?>"><label>Write or edit a brief<textarea name="content" required><?=e($brief['content']??'')?></textarea></label><button class="button secondary">Save manual brief</button></form></div><?php }}?>

